import java.util.*;

class Solution {
    public int authorScore(int[] citations) {
        Arrays.sort(citations);              // ascending order
        int n = citations.length;
        int h = 0;
        // walk from the most cited paper (end of the array) downwards
        for (int i = n - 1; i >= 0; i--) {
            int rank = n - i;                // 1 for the most cited paper
            if (citations[i] >= rank) {
                h = rank;
            } else {
                break;                       // later papers have even fewer citations
            }
        }
        return h;
    }
}

