function authorScore(citations) {
  const cnt = new Array(citations.length + 1).fill(0);
  for (const c of citations) cnt[Math.min(c, citations.length)]++;
  let seen = 0;
  for (let h = citations.length; h >= 0; h--) { seen += cnt[h]; if (seen >= h) return h; }
  return 0;
}
